package com.flowcanvas.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;
import java.util.UUID;

/**
 * A workflow graph: the named, persisted container of nodes and edges.
 *
 * <p>The identifier is generated by the server. Node and edge identifiers are generated by the
 * client so a canvas can be round-tripped without remapping, which is what lets the React
 * Flow frontend keep using its own handles while the graph is stored relationally.
 */
@Entity
@Table(name = "workflows")
public class Workflow {

    @Id
    private UUID id;

    @Column(name = "name", nullable = false, length = 120)
    private String name;

    @Column(name = "description", columnDefinition = "text")
    private String description;

    @Column(name = "status", nullable = false, length = 20)
    private String status = WorkflowStatus.DRAFT.name();

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    protected Workflow() {
        // for JPA
    }

    public Workflow(UUID id, String name, String description) {
        this.id = id;
        this.name = name;
        this.description = description;
        this.status = WorkflowStatus.DRAFT.name();
        this.createdAt = Instant.now();
        this.updatedAt = this.createdAt;
    }

    public UUID getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void touch() {
        this.updatedAt = Instant.now();
    }
}
